select case when p.cost >= 600 then 'high' when p.cost >= 340 then 'mid' else 'low' end as cost_bucket, max(i.quantity) - min(i.quantity) as quantity_range from inventory i left join products p on i.product_id = p.id group by case when p.cost >= 600 then 'high' when p.cost >= 340 then 'mid' else 'low' end having max(i.quantity) - min(i.quantity) > 61 order by cost_bucket desc, quantity_range;
